fn first_scalar(bytes: &[u8]) -> Option<(char, usize)> {
    let first = *bytes.first()?;
    let width = match first {
        0..=0x7f => 1,
        0xc2..=0xdf => 2,
        0xe0..=0xef => 3,
        0xf0..=0xf4 => 4,
        _ => return None,
    };
    Some((
        std::str::from_utf8(bytes.get(..width)?)
            .ok()?
            .chars()
            .next()?,
        width,
    ))
}
/// Raw UTF8-MAC source prefix reduced to one Word unit by the pinned buffer.
/// No suffix decoding/scanning: Hangul plus a bounded prefix-table query.
pub(super) fn mac_word_prefix(bytes: &[u8]) -> usize {
    if let Some((first, a)) = first_scalar(bytes)
        && let Some((second, b)) = first_scalar(&bytes[a..])
    {
        if ('\u{1100}'..='\u{1112}').contains(&first) && ('\u{1161}'..='\u{1175}').contains(&second)
        {
            let t = first_scalar(&bytes[a + b..])
                .filter(|(c, _)| ('\u{11a8}'..='\u{11c2}').contains(c))
                .map_or(0, |(_, n)| n);
            return a + b + t;
        }
        if ('\u{ac00}'..='\u{d7a3}').contains(&first)
            && (first as u32 - 0xac00).is_multiple_of(28)
            && ('\u{11a8}'..='\u{11c2}').contains(&second)
        {
            return a + b;
        }
    }
    for n in (3..=bytes.len().min(9)).rev() {
        if MAC.binary_search(&&bytes[..n]).is_ok() {
            return n;
        }
    }
    0
}
